/** The current hash's query, for URL round-trip assertions. */
export function hashQuery(): URLSearchParams {
  const h = window.location.hash;
  const i = h.indexOf("?");
  return new URLSearchParams(i === -1 ? "" : h.slice(i + 1));
}

