 *  codewords per group-1 block, blocks in group 2, data codewords per group-2 block]. */
const BLOCKS: readonly (readonly number[])[] = [
  [],
  [10, 1, 16, 0, 0],
  [16, 1, 28, 0, 0],
  [26, 1, 44, 0, 0],
  [18, 2, 32, 0, 0],
  [24, 2, 43, 0, 0],
  [16, 4, 27, 0, 0],
  [18, 4, 31, 0, 0],
  [22, 2, 38, 2, 39],
  [22, 3, 36, 2, 37],
  [26, 4, 43, 1, 44],
];

/** Alignment-pattern centre coordinates per version. */
const ALIGN: readonly (readonly number[])[] = [
  [],
  [],
  [6, 18],
  [6, 22],
  [6, 26],
  [6, 30],
  [6, 34],
  [6, 22, 38],
  [6, 24, 42],
  [6, 26, 46],
  [6, 28, 50],
];

const N1 = 3;
const N2 = 3;
const N3 = 40;
const N4 = 10;

/** The format-information bits for error-correction level M. */
const ECL_M_BITS = 0;

const EXP = new Uint8Array(512);
const LOG = new Uint8Array(256);
