function setCookies(res: Response): string[] {
  return (
    res.headers as unknown as { getSetCookie(): string[] }
  ).getSetCookie();
}

function cookieOf(res: Response, name: string): string | null {
  for (const c of setCookies(res)) {
    const [pair] = c.split(";");
    const [k, v] = pair!.split("=");
    if (k === name) return v ?? "";
  }
  return null;
}

